import{_ as i,C as a,c as o,o as e,j as t,G as r,b as l,a0 as n,a as s,w as d,a1 as c}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Processo decisionale basato sulla probabilità","description":"","frontmatter":{},"headers":[],"relativePath":"it/education/tactics/probability.md","filePath":"it/education/tactics/probability.md"}');const p=i({name:"it/education/tactics/probability.md"},[["render",function(i,u,p,b,m,h){const g=a("AdBanner"),v=a("Mermaid"),f=a("AdInArticle");return e(),o("div",null,[u[1]||(u[1]=t("h1",{id:"processo-decisionale-basato-sulla-probabilita",tabindex:"-1"},[s("Processo decisionale basato sulla probabilità "),t("a",{class:"header-anchor",href:"#processo-decisionale-basato-sulla-probabilita","aria-label":'Permalink to "Processo decisionale basato sulla probabilità"'},"​")],-1)),r(g),u[2]||(u[2]=t("p",null,"Il pensiero tattico d'élite sfrutta la probabilità per prendere decisioni migliori. Invece di tirare a indovinare o seguire l'istinto, si valutano sistematicamente le proprie opzioni.",-1)),u[3]||(u[3]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"La grande idea"),t("p",null,[t("strong",null,"Pensa in termini di probabilità, non di certezze."),s(" La decisione migliore non è sempre la più aggressiva o la più sicura: è quella che ti offre il miglior valore atteso in molte situazioni simili.")])],-1)),(e(),l(c,null,{default:d(()=>[r(v,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BPunto%20di%20decisione%5D%20--%3E%20B%5BOpzione%201%5D%0A%20%20%20%20A%20--%3E%20C%5BOpzione%202%5D%0A%20%20%20%20A%20--%3E%20D%5BOpzione%203%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BProbabilit%C3%A0%20di%20successo%5D%0A%20%20%20%20B%20--%3E%20F%5BRicompensa%20in%20caso%20di%20successo%5D%0A%20%20%20%20B%20--%3E%20G%5BCosto%20in%20caso%20di%20fallimento%5D%0A%0A%20%20%20%20C%20--%3E%20H%5BProbabilit%C3%A0%20di%20successo%5D%0A%20%20%20%20C%20--%3E%20I%5BRicompensa%20in%20caso%20di%20successo%5D%0A%20%20%20%20C%20--%3E%20J%5BCosto%20in%20caso%20di%20fallimento%5D%0A%0A%20%20%20%20D%20--%3E%20K%5BProbabilit%C3%A0%20di%20successo%5D%0A%20%20%20%20D%20--%3E%20L%5BRicompensa%20in%20caso%20di%20successo%5D%0A%20%20%20%20D%20--%3E%20M%5BCosto%20in%20caso%20di%20fallimento%5D%0A%0A%20%20%20%20E%20--%3E%20N%5BValore%20atteso%5D%0A%20%20%20%20F%20--%3E%20N%0A%20%20%20%20G%20--%3E%20N%0A%0A%20%20%20%20H%20--%3E%20O%5BValore%20atteso%5D%0A%20%20%20%20I%20--%3E%20O%0A%20%20%20%20J%20--%3E%20O%0A%0A%20%20%20%20K%20--%3E%20P%5BValore%20atteso%5D%0A%20%20%20%20L%20--%3E%20P%0A%20%20%20%20M%20--%3E%20P%0A%0A%20%20%20%20N%20--%3E%20Q%5BScegli%20il%20miglior%20veicolo%20elettrico%5D%0A%20%20%20%20O%20--%3E%20Q%0A%20%20%20%20P%20--%3E%20Q%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20Q%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...u[0]||(u[0]=[s(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=n('<h2 id="il-quadro-di-base" tabindex="-1">Il quadro di base <a class="header-anchor" href="#il-quadro-di-base" aria-label="Permalink to &quot;Il quadro di base&quot;">​</a></h2><p>Ogni lancio ha tre componenti:</p><table tabindex="0"><thead><tr><th>Componente</th><th>Domanda</th><th>Esempio</th></tr></thead><tbody><tr><td><strong>Probabilità di successo</strong></td><td>Quanto è probabile che io riesca a farlo?</td><td>Tasso di successo del 70% a questa distanza</td></tr><tr><td><strong>Ricompensa in caso di successo</strong></td><td>Cosa ci guadagno?</td><td>Vinci il punto, guadagna posizione</td></tr><tr><td><strong>Costo in caso di insuccesso</strong></td><td>Cosa perdo?</td><td>Dai un punto facile all&#39;avversario</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">La Formula</p><p><strong>Valore atteso = (Probabilità × Ricompensa) - ((1 - Probabilità) × Costo)</strong></p><p>Le buone decisioni massimizzano il valore atteso nel tempo.</p></div><h2 id="pensare-in-termini-di-probabilita" tabindex="-1">Pensare in termini di probabilità <a class="header-anchor" href="#pensare-in-termini-di-probabilita" aria-label="Permalink to &quot;Pensare in termini di probabilità&quot;">​</a></h2><p>Quando si decide tra le opzioni, considerare:</p><ul><li>Qual è il mio tasso di successo realistico per ciascuna opzione?</li><li>Cosa ci guadagno se funziona?</li><li>Qual è il costo se fallisce?</li><li>In che modo la situazione del gioco influenza la mia scelta?</li></ul><p>L&#39;opzione migliore non è sempre la più aggressiva o la più sicura: è quella che offre il risultato migliore in molte situazioni simili.</p><h2 id="conosci-i-tuoi-numeri" tabindex="-1">Conosci i tuoi numeri <a class="header-anchor" href="#conosci-i-tuoi-numeri" aria-label="Permalink to &quot;Conosci i tuoi numeri&quot;">​</a></h2><p>Per utilizzare il pensiero probabilistico, è necessario conoscere i tassi di successo effettivi:</p><table tabindex="0"><thead><tr><th>Tipo di lancio</th><th>Distanza</th><th>Il tuo tasso di successo</th></tr></thead><tbody><tr><td>Punto (vicino)</td><td>6-7 mesi</td><td>___%</td></tr><tr><td>Punto (medio)</td><td>8-9 mesi</td><td>___%</td></tr><tr><td>Punto (lungo)</td><td>10m+</td><td>___%</td></tr><tr><td>Spara (da vicino)</td><td>6-7 mesi</td><td>___%</td></tr><tr><td>Spara (media)</td><td>8-9 mesi</td><td>___%</td></tr><tr><td>Spara (lungo)</td><td>10m+</td><td>___%</td></tr></tbody></table>',11)),r(f),u[5]||(u[5]=n('<p>Tieni traccia di questi risultati nella pratica. Sii onesto: la maggior parte dei giocatori sopravvaluta le proprie percentuali di successo.</p><h2 id="adattamento-alle-condizioni" tabindex="-1">Adattamento alle condizioni <a class="header-anchor" href="#adattamento-alle-condizioni" aria-label="Permalink to &quot;Adattamento alle condizioni&quot;">​</a></h2><p>Le tariffe base variano in base a:</p><table tabindex="0"><thead><tr><th>Fattore</th><th>Effetto sul tasso di successo</th></tr></thead><tbody><tr><td>Terreno sconosciuto</td><td>-10 a -20%</td></tr><tr><td>Situazione di pressione</td><td>-5 a -15%</td></tr><tr><td>Fatica</td><td>-5 a -10%</td></tr><tr><td>Fiducia (alta)</td><td>+5 a +10%</td></tr><tr><td>Successo recente</td><td>+5%</td></tr><tr><td>fallimento recente</td><td>-5 a -10%</td></tr></tbody></table><p>Siate realistici riguardo a questi adattamenti.</p><h2 id="il-principio-del-vantaggio-di-boule" tabindex="-1">Il principio del vantaggio di Boule <a class="header-anchor" href="#il-principio-del-vantaggio-di-boule" aria-label="Permalink to &quot;Il principio del vantaggio di Boule&quot;">​</a></h2><p>Quando hai più bocce rimanenti del tuo avversario:</p><p><strong>Priorità 1: proteggere il punto</strong></p><ul><li>Per prima cosa, assicurati di avere almeno un punto</li><li>Non essere avido prima di aver assicurato le basi</li></ul><p><strong>Priorità 2: Massimizzare i punti con un rischio calcolato</strong></p><ul><li>Una volta che sei in possesso, valuta se puoi aggiungere altri punti</li><li>Ogni lancio aggiuntivo è una decisione rischio/ricompensa</li><li>Non trasformare una vittoria sicura di 2 punti in una sconfitta esagerando</li></ul><p><strong>Meno bocce rimanenti:</strong> Devi far sì che ogni tiro conti. Le giocate sicure potrebbero non essere sufficienti: prendi in considerazione opzioni con ricompense più elevate per recuperare alla fine.</p><h2 id="il-principio-quot-une-boule-devant-quot" tabindex="-1">Il principio &quot;Une Boule Devant&quot;. <a class="header-anchor" href="#il-principio-quot-une-boule-devant-quot" aria-label="Permalink to &quot;Il principio &amp;quot;Une Boule Devant&amp;quot;.&quot;">​</a></h2><p>Una boccia posta davanti al pallino (tra il pallino e l&#39;avversario) è estremamente preziosa:</p><ul><li>Blocca le linee di puntamento diretto</li><li>Costringe gli avversari a girare intorno o sopra</li><li>Può deviare le bocce in arrivo</li><li>È una &quot;moneta&quot; che vale la pena proteggere</li></ul><p><strong>Implicazione tattica:</strong> A volte è meglio piazzare una boccia bloccante piuttosto che cercare di avvicinarsi il più possibile.</p><h2 id="tolleranza-al-rischio-per-stato-del-gioco" tabindex="-1">Tolleranza al rischio per stato del gioco <a class="header-anchor" href="#tolleranza-al-rischio-per-stato-del-gioco" aria-label="Permalink to &quot;Tolleranza al rischio per stato del gioco&quot;">​</a></h2><h3 id="con-limite-di-tempo" tabindex="-1">Con limite di tempo <a class="header-anchor" href="#con-limite-di-tempo" aria-label="Permalink to &quot;Con limite di tempo&quot;">​</a></h3><p>Quando si gioca con un limite di tempo, la differenza di punteggio è importante:</p><table tabindex="0"><thead><tr><th>Situazione del punteggio</th><th>Approccio al rischio</th></tr></thead><tbody><tr><td>In vantaggio di 4+</td><td>Molto conservativo: proteggere il vantaggio, far scorrere il tempo</td></tr><tr><td>In vantaggio per 1-3</td><td>Conservatore - non regalare punti</td></tr><tr><td>Legato</td><td>Bilanciato - rischi calcolati</td></tr><tr><td>Dietro di 1-3</td><td>Aggressivo - bisogno di guadagnare terreno</td></tr><tr><td>Dietro di 4+</td><td>Molto aggressivo - bisogna correre dei rischi, il tempo stringe</td></tr></tbody></table><h3 id="senza-limiti-di-tempo" tabindex="-1">Senza limiti di tempo <a class="header-anchor" href="#senza-limiti-di-tempo" aria-label="Permalink to &quot;Senza limiti di tempo&quot;">​</a></h3><p>Quando non c&#39;è pressione di tempo:</p><ul><li>Mantieni il tuo piano di gioco: non cambiare strategia solo in base al punteggio</li><li>Il punteggio oscillerà: fidati del tuo approccio</li><li>Prendi in considerazione di cambiare il tuo piano di gioco solo se è chiaro che non funziona contro questo avversario</li><li>I cambiamenti dovuti al panico quando si è indietro spesso peggiorano le cose</li></ul><h3 id="modifiche-di-fine-partita" tabindex="-1">Modifiche di fine partita <a class="header-anchor" href="#modifiche-di-fine-partita" aria-label="Permalink to &quot;Modifiche di fine partita&quot;">​</a></h3><p><strong>Se vincere questa estremità significa vincere la partita:</strong></p><ul><li>Sii più conservatore</li><li>Non rischiare di regalare più punti</li><li>Un singolo punto potrebbe essere sufficiente</li></ul><p><strong>Se si perde questa estremità si perde la partita:</strong></p><ul><li>Prendi rischi più grandi</li><li>Bisogno di segnare più punti</li><li>Il gioco sicuro non ti salverà</li></ul><h2 id="errori-comuni-di-probabilita" tabindex="-1">Errori comuni di probabilità <a class="header-anchor" href="#errori-comuni-di-probabilita" aria-label="Permalink to &quot;Errori comuni di probabilità&quot;">​</a></h2><h3 id="_1-eccessiva-sicurezza" tabindex="-1">1. Eccessiva sicurezza <a class="header-anchor" href="#_1-eccessiva-sicurezza" aria-label="Permalink to &quot;1. Eccessiva sicurezza&quot;">​</a></h3><p>&quot;Posso fare quel tiro&quot;, ma riesci a farlo 7 volte su 10? Sii onesto.</p><h3 id="_2-ignorare-i-tassi-di-base" tabindex="-1">2. Ignorare i tassi di base <a class="header-anchor" href="#_2-ignorare-i-tassi-di-base" aria-label="Permalink to &quot;2. Ignorare i tassi di base&quot;">​</a></h3><p>La tua percentuale di tiro non cambia perché il momento è importante.</p><h3 id="_3-fallacia-dei-costi-irrecuperabili" tabindex="-1">3. Fallacia dei costi irrecuperabili <a class="header-anchor" href="#_3-fallacia-dei-costi-irrecuperabili" aria-label="Permalink to &quot;3. Fallacia dei costi irrecuperabili&quot;">​</a></h3><p>&quot;Ho già sbagliato due volte, dovrei continuare a tirare&quot; - ogni tiro è indipendente.</p><h3 id="_4-distorsione-del-risultato" tabindex="-1">4. Distorsione del risultato <a class="header-anchor" href="#_4-distorsione-del-risultato" aria-label="Permalink to &quot;4. Distorsione del risultato&quot;">​</a></h3><p>Un tiro rischioso che ha funzionato era comunque rischioso. Una giocata sicura che ha fallito era comunque corretta.</p><h3 id="_5-ignorare-le-opzioni-dell-39-avversario" tabindex="-1">5. Ignorare le opzioni dell&#39;avversario <a class="header-anchor" href="#_5-ignorare-le-opzioni-dell-39-avversario" aria-label="Permalink to &quot;5. Ignorare le opzioni dell&amp;#39;avversario&quot;">​</a></h3><p>Considera cosa faranno dopo il tuo lancio, che abbia successo o meno.</p><h2 id="applicazione-pratica" tabindex="-1">Applicazione pratica <a class="header-anchor" href="#applicazione-pratica" aria-label="Permalink to &quot;Applicazione pratica&quot;">​</a></h2><h3 id="prima-di-ogni-lancio" tabindex="-1">Prima di ogni lancio <a class="header-anchor" href="#prima-di-ogni-lancio" aria-label="Permalink to &quot;Prima di ogni lancio&quot;">​</a></h3><ol><li><strong>Identifica le opzioni</strong> (punta, spara, blocca, ecc.)</li><li><strong>Stima la probabilità di successo</strong> per ogni</li><li><strong>Considera i risultati</strong> (successo e fallimento)</li><li><strong>Fattore sullo stato del gioco</strong> (punteggio, bocce rimanenti)</li><li><strong>Scegli</strong> l&#39;opzione con il miglior valore atteso</li><li><strong>Impegno completo</strong> - nessuna incertezza durante l&#39;esecuzione</li></ol><h3 id="costruire-l-39-intuizione" tabindex="-1">Costruire l&#39;intuizione <a class="header-anchor" href="#costruire-l-39-intuizione" aria-label="Permalink to &quot;Costruire l&amp;#39;intuizione&quot;">​</a></h3><p>Col tempo, il pensiero probabilistico diventa intuitivo:</p><ul><li>Tieni traccia dei tuoi risultati onestamente</li><li>Rivedere le decisioni dopo le partite</li><li>Nota i modelli nei tuoi tassi di successo</li><li>Adatta il tuo modello mentale</li></ul><h2 id="conclusione-chiave" tabindex="-1">Conclusione chiave <a class="header-anchor" href="#conclusione-chiave" aria-label="Permalink to &quot;Conclusione chiave&quot;">​</a></h2><blockquote><p>Le buone decisioni non sempre portano a buoni risultati. Ma col tempo, le buone decisioni portano a risultati migliori.</p></blockquote><p>Pensa in termini di probabilità. Conosci i tuoi numeri. Fai la mossa intelligente, non quella ottimistica.</p>',48)),r(g)])}]]);export{u as __pageData,p as default};
